package com.example.todo.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="app_users") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=150) private String username; @Column(nullable=false) private String password; }
